    def test_verify(
        self,
        name: str,
        pk_bytes: bytes,
        msg: bytes,
        ctx: bytes,
        sig: bytes,
        expected: bool,
    ):
        dsa = ML_DSA(ParameterSet.ML_DSA_44)

        try:
            pk = VerificationKey.from_bytes(pk_bytes)
        except ValueError:
            self.assertFalse(expected)
        else:
            actual = dsa.verify(pk, sig, msg, ctx)
            self.assertIs(actual, expected)
